498			t.Fatal("台账B数据被 A 污染")
499		}
500	
501		// 在重开的台账 A 上继续操作并再次持久化。
502		if err := reopenedA.SetStatus("ONLY-A", StatusRetired); err != nil {
503			t.Fatalf("在重开的台账上操作失败: %v", err)
504		}
505		again, _ := openAt(pathA, clock)
506		if again.findInstrument("ONLY-A").Status != StatusRetired {
507			t.Fatal("重开后所做的操作没有保存")
508		}
